<script setup lang="ts">
import { Text } from '@/shared/ui/text/paragraph';
import { RouterLink } from 'vue-router';
import { Button } from '@/shared/ui/button';
import { useGlobalForm } from '@/shared/composables/useGlobalForm';
import { ref } from 'vue';

const { openForm } = useGlobalForm();
const isHovered = ref(false);

const handleButtonClick = () => {
    openForm();
};

const handleMouseEnter = () => {
    isHovered.value = true;
};

const handleMouseLeave = () => {
    isHovered.value = false;
};

interface cardData {
    name: string,
    link: string,
    img?: string,
    availability?: string
}[]

const cardData = defineProps<{
    data: cardData
}>()
</script>

<template>
    <div class="catalog-card" @mouseenter="handleMouseEnter" @mouseleave="handleMouseLeave">
        <RouterLink :to="data.link" class="card-content">
            <img :src="data.img" :alt="data.name">
            <Text tag-name="span" size="xl" color="dark-first" class="card__text-title">
                {{ data.name }}
            </Text>
            <Text tag-name="span" size="s" color="dark-gray2" class="card__text-title">
                {{ data.availability }}
            </Text>
        </RouterLink>
        <Button tagName="button" size="xs" color="accent" @click="handleButtonClick"
            :class="['order-button', { 'order-button--visible': isHovered }]">
            <Text tag-name="span" size="l" color="white">
                Заказать
            </Text>
        </Button>
    </div>
</template>

<style lang="scss" scoped>
.catalog-card {
    padding: 25px 30px;
    border: 1px solid #f2f2f2;
    display: flex;
    align-items: start;
    justify-content: center;
    position: relative;
    overflow: hidden;


    &:hover {
        box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.15);

        .order-button {
            transform: translateX(-50%) translateY(0);
            opacity: 1;
        }

        .card-content {
            .card__text-title {
                display: none;
            }
        }

    }


    .card-content {
        display: flex;
        flex-direction: column;
        align-items: center;


        img {
            width: 200px;
            height: 200px;
        }

        .card__text-title {
            position: relative;
            margin-top: 17px;
            max-width: 200px;
            text-align: center;
        }
    }

    .order-button {
        position: absolute;
        bottom: 16px;
        left: 50%;
        transform: translateX(-50%) translateY(100%);
        opacity: 0;
        transition: all 0.3s ease;
        z-index: 10;
    }


}

@media screen and (max-width: 541px) {
    .catalog-card {
        width: 100%;
    }
}</style>